\title{The Finite-Kernel Criterion for Automatic Sequences:\\ A Composition-Law Foundation}
\author{Aristotle}
\date{2026-07-12}

\begin{document}

\begin{abstract}
An \emph{automatic sequence} is a sequence whose $n$-th term is produced by
feeding the base-$k$ digits of $n$ into a deterministic finite automaton and
reading a state-dependent output. We develop the theory of automatic sequences
entirely through the \emph{kernel criterion}, avoiding automata as primitive
objects. For a base $k \ge 2$ and a sequence $a : \N \to S$, we define the
\emph{decimation} $a_{i,r} : n \mapsto a(k^{i} n + r)$ and the \emph{$k$-kernel}
as the set of all decimations with offset $r < k^{i}$. A sequence is
\emph{$k$-automatic} when its $k$-kernel is finite (Eilenberg's criterion). Our
central structural result is a single \emph{decimation semigroup law}: the
composite of two decimations is again a decimation, with explicit parameters.
From this one identity we derive that the kernel is closed under decimation, that
automaticity is preserved by constants, output codings, and arbitrary pointwise
binary combinations, and that every automatic sequence has finite range. We treat
the \emph{Thue--Morse sequence} as the canonical example: it satisfies the base-$2$
recurrence $t_{2n} = t_n$, $t_{2n+1} = t_n + 1$ over $\mathbb{Z}/2$, its
$2$-kernel is exactly $\{t, t+1\}$, and consequently it is $2$-automatic with a
two-state kernel. Finally we establish an exact dictionary between the additive
parity form $t_n \in \{0,1\}$ and the multiplicative sign form
$\varepsilon_n = (-1)^{t_n} \in \{\pm 1\}$.
\end{abstract}

\maketitle

\section{Introduction}

Automatic sequences are the sequences computable by the weakest interesting model
of computation: a deterministic finite automaton with no auxiliary memory. One
feeds the digits of an index $n$ (in a fixed base $k$) into the automaton and
records an output attached to the final state. Despite this severe restriction,
the class captures a remarkable menagerie of number-theoretic objects---the
Thue--Morse sequence, the Rudin--Shapiro sequence, the regular paperfolding
sequence---and enjoys a rich algebraic and logical theory.

There are two standard vantage points. The \emph{operational} one takes the
automaton as primitive. The \emph{combinatorial} one, due to Eilenberg,
characterizes automaticity intrinsically: a sequence is $k$-automatic iff its
\emph{$k$-kernel}---the collection of subsequences obtained by sampling along
power-of-$k$ arithmetic progressions---is finite. This paper takes the kernel
criterion as the definition and shows how far a single composition identity
carries. The organizing principle is that \emph{decimations compose}: sampling
along one power-of-$k$ progression and then along another is the same as sampling
along a single, explicitly computable progression.

\section{Notation}

Throughout, $\N = \{0, 1, 2, \dots\}$, the base $k$ is a natural number (the
interesting range is $k \ge 2$), and $S, T, U$ are arbitrary output alphabets. A
\emph{sequence} over $S$ is a function $a : \N \to S$. We write $s_2(n)$ for the
number of $1$-digits in the binary expansion of $n$. We repeatedly use that a
subset of a finite set is finite and that the image of a finite set under a
function is finite.

\section{The kernel criterion}

\begin{definition}[Decimation]
For a base $k$, a sequence $a : \N \to S$, and $i, r \in \N$, the
\emph{$(i,r)$-decimation} of $a$ is
\[
  a_{i,r} : \N \to S, \qquad a_{i,r}(n) = a\big(k^{i} n + r\big).
\]
\end{definition}

When $k = 2$, $i = 1$, the two decimations $a_{1,0}$ and $a_{1,1}$ are the even-
and odd-indexed subsequences.

\begin{definition}[$k$-kernel]
The \emph{$k$-kernel} of $a$ is
\[
  \Kk_k(a) = \big\{\, a_{i,r} : i, r \in \N,\ r < k^{i} \,\big\}.
\]
\end{definition}

\begin{definition}[Automaticity]
A sequence $a$ is \emph{$k$-automatic} if $\Kk_k(a)$ is finite.
\end{definition}

\begin{lemma}[Trivial decimation]
$a_{0,0} = a$; in particular $a \in \Kk_k(a)$.
\end{lemma}
\begin{proof}
$a_{0,0}(n) = a(k^{0} n + 0) = a(n)$; take $i = r = 0$ with $0 < k^0 = 1$.
\end{proof}

\section{The composition law}

\begin{theorem}[Decimation semigroup law]\label{thm:comp}
For every base $k$, sequence $a$, and $i, r, j, s$,
\[
  \big(a_{i,r}\big)_{j,s} = a_{\,i+j,\ k^{i} s + r}.
\]
\end{theorem}
\begin{proof}
Evaluate at $n$:
$\big(a_{i,r}\big)_{j,s}(n) = a_{i,r}(k^{j} n + s) = a(k^{i}(k^{j} n + s) + r)
= a(k^{i+j} n + k^{i} s + r)$, which equals
$a_{\,i+j,\ k^{i} s + r}(n)$.
\end{proof}

\begin{theorem}[Kernel closure]\label{thm:closure}
If $b \in \Kk_k(a)$, then $\Kk_k(b) \subseteq \Kk_k(a)$.
\end{theorem}
\begin{proof}
Write $b = a_{i,r}$ with $r < k^{i}$, and let $c = b_{j,s}$ with $s < k^{j}$. By
Theorem~\ref{thm:comp}, $c = a_{\,i+j,\ k^{i} s + r}$. Since $s + 1 \le k^{j}$ and
$r < k^{i}$,
\[
  k^{i} s + r < k^{i} s + k^{i} = k^{i}(s + 1) \le k^{i} k^{j} = k^{i+j},
\]
so $c \in \Kk_k(a)$.
\end{proof}

\begin{corollary}
If $a$ is $k$-automatic and $b \in \Kk_k(a)$, then $b$ is $k$-automatic.
\end{corollary}

\section{Closure properties}

\begin{proposition}[Constants]
For any $c \in S$, the constant sequence $n \mapsto c$ is $k$-automatic.
\end{proposition}
\begin{proof}
Every decimation of a constant is that same constant, so the kernel is a subset of
a singleton.
\end{proof}

\begin{lemma}\label{lem:code}
For $g : S \to T$, $\big(g \circ a\big)_{i,r} = g \circ \big(a_{i,r}\big)$.
\end{lemma}
\begin{proof}
Both send $n$ to $g(a(k^{i} n + r))$.
\end{proof}

\begin{theorem}[Closure under output codings]
If $a$ is $k$-automatic and $g : S \to T$, then $g \circ a$ is $k$-automatic.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:code}, $\Kk_k(g \circ a)$ is contained in the image of the
finite set $\Kk_k(a)$ under $b \mapsto g \circ b$.
\end{proof}

\begin{lemma}\label{lem:pw}
For $f : S \to T \to U$,
$\big(n \mapsto f(a_n, b_n)\big)_{i,r} = \big(n \mapsto f(a_{i,r}(n), b_{i,r}(n))\big)$.
\end{lemma}
\begin{proof}
Both send $n$ to $f(a(k^{i} n + r), b(k^{i} n + r))$.
\end{proof}

\begin{theorem}[Closure under pointwise operations]
If $a$ and $b$ are $k$-automatic and $f : S \to T \to U$, then
$n \mapsto f(a_n, b_n)$ is $k$-automatic. In particular, over a ring the pointwise
sum and product are $k$-automatic.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:pw}, each decimation is the image of the pair
$(a_{i,r}, b_{i,r}) \in \Kk_k(a) \times \Kk_k(b)$ under
$(p,q) \mapsto (n \mapsto f(p(n), q(n)))$; a product of finite sets is finite, and
its image is finite.
\end{proof}

\begin{theorem}[Finite range]
If $a$ is $k$-automatic with $k \ge 2$, then $\{a_n : n \in \N\}$ is finite.
\end{theorem}
\begin{proof}
The map $b \mapsto b(0)$ sends the finite set $\Kk_k(a)$ to a finite subset of $S$.
For each $n$, choosing $i$ with $n < k^{i}$ and offset $r = n$ gives
$a_{i,n}(0) = a(n)$, so $a_n$ lies in that finite image.
\end{proof}

\section{The Thue--Morse sequence}

Fix $k = 2$, outputs in $\mathbb{Z}/2$, and define $t_n = s_2(n) \bmod 2$, the
parity of the number of $1$-digits of $n$: $0,1,1,0,1,0,0,1,\dots$

\begin{lemma}[Automaton recurrence]\label{lem:tm}
$t_{2n} = t_n$ and $t_{2n+1} = t_n + 1$ in $\mathbb{Z}/2$.
\end{lemma}
\begin{proof}
Appending the digit $0$ leaves the digit sum unchanged; appending $1$ increases it
by one.
\end{proof}

\begin{theorem}[Exact kernel]\label{thm:tmk}
$\Kk_2(t) = \{\, t,\ t + 1 \,\}$.
\end{theorem}
\begin{proof}
$(\supseteq)$ $t = t_{0,0}$ and $t + 1 = t_{1,1}$ by Lemma~\ref{lem:tm}.

$(\subseteq)$ Induct on depth $i$ that every $t_{i,r}$ (with $r < 2^i$) is $t$ or
$t+1$. Base $i=0$: $t_{0,0} = t$. Step: by Theorem~\ref{thm:comp} a depth-$(i+1)$
decimation is a depth-$1$ decimation of a depth-$i$ decimation, which by induction
is $t$ or $t+1$. Using Lemma~\ref{lem:tm} and the involution $x \mapsto x+1$ on
$\mathbb{Z}/2$,
\[
  t_{1,0} = t,\quad t_{1,1} = t+1,\quad (t+1)_{1,0} = t+1,\quad (t+1)_{1,1} = t,
\]
all in $\{t, t+1\}$.
\end{proof}

\begin{corollary}
The Thue--Morse sequence is $2$-automatic.
\end{corollary}

\section{Parity and sign}

Define the \emph{sign form} $\varepsilon_n = (-1)^{s_2(n)} \in \{+1, -1\}$.

\begin{proposition}[Parity--sign dictionary]
For all $n$: $t_n = 0 \iff \varepsilon_n = +1$ and $t_n = 1 \iff \varepsilon_n = -1$.
\end{proposition}
\begin{proof}
$\varepsilon_n = (-1)^{s_2(n)}$ depends only on $s_2(n) \bmod 2 = t_n$.
\end{proof}

The additive form places Thue--Morse in $\mathbb{Z}/2$, where the transition is
addition; the multiplicative form places it in $\{\pm 1\}$, where the same
transition is multiplication by $-1$. Closure under output codings transports
automaticity between the two.

\section{Applications and future work}

\subsection*{Applications}
Equality of two automatic sequences over the same base is decidable via their
finite kernels; the Thue--Morse and Rudin--Shapiro sequences underpin
low-autocorrelation code design; the Thue--Morse ordering yields balanced
scheduling with $O(\log n)$-time access; and automatic sequences form a decidable
island bordering the undecidable landscape of general computable sequences.

\begin{conjecture}[Kernel size equals minimal state count]
For every $k \ge 2$ and every $k$-automatic sequence, the number of distinct
decimations equals the number of states of the minimal generating automaton; a
sequence with a kernel of size $m$ requires at least $m$ states.
\end{conjecture}

\begin{conjecture}[Multiplicative bases]
A sequence that is both $k$- and $\ell$-automatic for multiplicatively independent
$k, \ell$ is eventually periodic, with both kernel sizes bounded by the eventual
period.
\end{conjecture}

\begin{conjecture}[Convolution closure]
If $a, b$ are $p$-automatic with values in $\mathbb{Z}/p$, then the running sum and
the mod-$p$ Cauchy convolution $n \mapsto \sum_{i \le n} a_i \, b_{n-i}$ are
$p$-automatic.
\end{conjecture}

\section{Conclusion}

A single composition identity---the decimation semigroup law---suffices to erect
the structural theory of automatic sequences: kernel closure, algebraic closure
properties, and finiteness of range all follow. The Thue--Morse sequence realizes
the theory with the smallest nontrivial kernel $\{t, t+1\}$, and its parity and
sign forms are two faithful costumes for the same object.

