"""Automaticity test via finite-kernel enumeration."""
from __future__ import annotations
from typing import Callable, Dict, List, Tuple


def thue_morse(n: int) -> int:
    return bin(n).count("1") % 2


def decimate(a: Callable[[int], int], k: int, i: int, r: int) -> Callable[[int], int]:
    step = k ** i
    return lambda n: a(step * n + r)


def prefix(a: Callable[[int], int], length: int) -> Tuple[int, ...]:
    return tuple(a(n) for n in range(length))


def kernel_size(a: Callable[[int], int], k: int, max_depth: int, horizon: int) -> int:
    """Number of distinct decimations a_{i,r} (0<=i<=max_depth, r<k^i)."""
    seen: set = set()
    for i in range(max_depth + 1):
        for r in range(k ** i):
            seen.add(prefix(decimate(a, k, i, r), horizon))
    return len(seen)


if __name__ == "__main__":
    for d in range(8):
        print(f"depth {d}: kernel size {kernel_size(thue_morse, 2, d, 64)}")
    # stabilizes at 2 -> Thue-Morse is 2-automatic with a two-state kernel.

"""Thue-Morse automaton recurrence: t(2n)=t(n), t(2n+1)=t(n)+1 mod 2."""
from __future__ import annotations


def thue_morse(n: int) -> int:
    return bin(n).count("1") % 2


def check_recurrence(bound: int) -> bool:
    for n in range(bound):
        if thue_morse(2 * n) != thue_morse(n):
            return False
        if thue_morse(2 * n + 1) != (thue_morse(n) + 1) % 2:
            return False
    return True


if __name__ == "__main__":
    print("recurrence holds up to n=100000:", check_recurrence(100000))

"""Closure of the automatic class under coding and pointwise product."""
from __future__ import annotations
from typing import Callable, Tuple


def thue_morse(n: int) -> int:
    return bin(n).count("1") % 2


def rudin_shapiro(n: int) -> int:
    b = bin(n)[2:]
    return sum(1 for i in range(len(b) - 1) if b[i] == b[i + 1] == "1") % 2


def decimate(a, k, i, r):
    step = k ** i
    return lambda n: a(step * n + r)


def kernel_size(a, k, max_depth, horizon) -> int:
    seen = set()
    for i in range(max_depth + 1):
        for r in range(k ** i):
            d = decimate(a, k, i, r)
            seen.add(tuple(d(n) for n in range(horizon)))
    return len(seen)


if __name__ == "__main__":
    sign = lambda n: -1 if thue_morse(n) else 1        # output coding
    prod = lambda n: thue_morse(n) * rudin_shapiro(n)  # pointwise product
    print("Thue-Morse kernel:", kernel_size(thue_morse, 2, 6, 64))
    print("coded sign kernel:", kernel_size(sign, 2, 6, 64))
    print("TM*RS product kernel:", kernel_size(prod, 2, 7, 64))
